s18-minimum-number-of-bracket-reversals-.code:
// Approach: An odd-length brace string cannot balance. Cancel matched pairs; the remaining opens and
//   closes need ceil(count/2) flips each.
#include <string>
using namespace std;
int minimumBraceReversals(const string& braces) {
    // An odd number of braces cannot be paired by any reversals.
    if (braces.size() % 2) return -1;
    int opens = 0, closes = 0;
    for (char ch : braces) {
        // Count unmatched opening braces; closing braces cancel one when possible.
        if (ch == '{') ++opens;
        else if (opens) --opens; // match with an earlier open
        else ++closes;
    }
    return (opens + 1) / 2 + (closes + 1) / 2;
}

s18-count-and-say.code:
// Approach: Build each term by grouping consecutive equal digits in the previous term and writing
//   count followed by digit.
#include <string>
using namespace std;
string countAndSay(int n) {
    // Read each run as its count followed by its digit.
    if (n <= 0) return "";
    string current = "1";
    for (int term = 2; term <= n; ++term) {
        string next;
        for (int i = 0; i < (int)current.size();) {
            int j = i;
            // Move j past the whole run of equal digits, then describe its count and digit.
            while (j < (int)current.size() && current[j] == current[i]) ++j;
            next += to_string(j - i);
            next += current[i];
            i = j;
        }
        current.swap(next);
    }
    return current;
}

s18-hashing-in-strings-theory.code:
// Approach: A polynomial rolling hash combines characters in order. Equal strings hash equally;
//   unequal strings can still collide, so verify matches.
#include <cstdint>
#include <string>
using namespace std;
uint64_t polynomialHash(const string& s) {
    const uint64_t MOD = 1000000007ULL, BASE = 911382323ULL;
    uint64_t hash = 0;
    // Fold each byte into the rolling hash in the same order as the string.
    for (unsigned char ch : s)
        hash = (hash * BASE + ch + 1) % MOD;
    return hash;
}
// A hash is a filter, not a proof of string equality.

s18-rabin-karp.code:
// Approach: Slide a fixed-length polynomial hash across the text. Verify characters on a hash match
//   to handle collisions.
#include <cstdint>
#include <string>
#include <vector>
using namespace std;
vector<int> rabinKarp(const string& text, const string& pattern) {
    // A rolling hash updates the window without recounting every character.
    const uint64_t MOD = 1000000007ULL, BASE = 257ULL;
    int n = (int)text.size(), m = (int)pattern.size();
    vector<int> positions;
    // The empty pattern matches at every boundary, including the end.
    if (m == 0) {
        for (int i = 0; i <= n; ++i) positions.push_back(i);
        return positions;
    }
    // A longer pattern cannot fit anywhere in the text.
    if (m > n) return positions;
    uint64_t target = 0, window = 0, highest = 1;
    for (int i = 0; i < m; ++i) {
        target = (target * BASE + (unsigned char)pattern[i] + 1) % MOD;
        window = (window * BASE + (unsigned char)text[i] + 1) % MOD;
        // Compute BASE^(m-1) for removing a window's outgoing character.
        if (i + 1 < m) highest = highest * BASE % MOD;
    }
    // Check every length-m window, then roll the hash forward by one character.
    for (int start = 0; start + m <= n; ++start) {
        // A matching hash is only a candidate; compare actual characters to avoid collisions.
        if (window == target && text.compare(start, m, pattern) == 0)
            positions.push_back(start);
        // Only roll the hash when another complete window follows.
        if (start + m < n) {
            uint64_t outgoing = ((unsigned char)text[start] + 1) * highest % MOD;
            window = (window + MOD - outgoing) % MOD;
            window = (window * BASE + (unsigned char)text[start + m] + 1) % MOD;
        }
    }
    return positions;
}

s18-z-function.code:
// Approach: Maintain the rightmost substring known to match the prefix; reuse its Z-values and extend
//   only beyond that window.
#include <algorithm>
#include <string>
#include <vector>
using namespace std;
vector<int> zFunction(const string& s) {
    // Z[i] counts characters matching the string prefix from position i.
    int n = (int)s.size();
    vector<int> z(n, 0);
    for (int i = 1, left = 0, right = 0; i < n; ++i) {
        // Reuse a previously matched Z-box when this position lies inside it.
        if (i <= right) z[i] = min(right - i + 1, z[i - left]);
        // Extend the match beyond the copied Z-box as long as prefix characters agree.
        while (i + z[i] < n && s[z[i]] == s[i + z[i]]) ++z[i];
        // Extend the saved Z-box when the current match reaches farther right.
        if (i + z[i] - 1 > right) {
            left = i;
            right = i + z[i] - 1;
        }
    }
    return z;
}

s18-kmp-algo-lps-pi-array.code:
// Approach: The LPS array tells how far a partial match can fall back without rechecking text
//   characters.
#include <string>
#include <vector>
using namespace std;
vector<int> prefixFunction(const string& pattern) {
    vector<int> lps(pattern.size(), 0);
    for (int i = 1; i < (int)pattern.size(); ++i) {
        int j = lps[i - 1];
        // On mismatch, reuse the longest shorter prefix already known to match.
        while (j > 0 && pattern[i] != pattern[j]) j = lps[j - 1];
        // Extend the prefix length when the new character matches.
        if (pattern[i] == pattern[j]) ++j;
        lps[i] = j;
    }
    return lps;
}
vector<int> kmpSearch(const string& text, const string& pattern) {
    vector<int> positions;
    // An empty pattern matches at every text boundary.
    if (pattern.empty()) return positions;
    vector<int> lps = prefixFunction(pattern);
    int j = 0;
    for (int i = 0; i < (int)text.size(); ++i) {
        // On a text mismatch, skip comparisons covered by a previous prefix match.
        while (j > 0 && text[i] != pattern[j]) j = lps[j - 1];
        // Advance the pattern pointer after a matching text character.
        if (text[i] == pattern[j]) ++j;
        // A full pattern match starts at the current index minus its length plus one.
        if (j == (int)pattern.size()) {
            positions.push_back(i - j + 1);
            j = lps[j - 1]; // allow overlapping matches
        }
    }
    return positions;
}

s18-shortest-palindrome.code:
// Approach: Find the longest palindromic prefix with a prefix-function scan of s + sentinel +
//   reverse(s), then prepend the remaining reversed suffix.
#include <algorithm>
#include <string>
#include <vector>
using namespace std;
string shortestPalindrome(const string& s) {
    string reversed(s.rbegin(), s.rend());
    // Use an integer sentinel outside the byte alphabet.
    vector<int> sequence;
    for (unsigned char ch : s) sequence.push_back(ch);
    sequence.push_back(256);
    for (unsigned char ch : reversed) sequence.push_back(ch);
    vector<int> lps(sequence.size(), 0);
    for (int i = 1; i < (int)sequence.size(); ++i) {
        int j = lps[i - 1];
        // Fall back to a shorter matching prefix without restarting the scan.
        while (j > 0 && sequence[i] != sequence[j]) j = lps[j - 1];
        // Extend the matching prefix while building the LPS array.
        if (sequence[i] == sequence[j]) ++j;
        lps[i] = j;
    }
    int prefix = lps.back();
    return reversed.substr(0, s.size() - prefix) + s;
}

s18-longest-happy-prefix.code:
// Approach: The last LPS value is the longest proper prefix that is also a suffix.
#include <string>
#include <vector>
using namespace std;
string longestHappyPrefix(const string& s) {
    // An empty string has no nonempty proper prefix.
    if (s.empty()) return "";
    // lps[i] is the longest proper prefix matching a suffix ending at i.
    vector<int> lps(s.size(), 0);
    for (int i = 1; i < (int)s.size(); ++i) {
        int j = lps[i - 1];
        // Use the LPS fallback to keep only a shorter valid prefix candidate.
        while (j > 0 && s[i] != s[j]) j = lps[j - 1];
        // Extend the current prefix/suffix match when characters agree.
        if (s[i] == s[j]) ++j;
        lps[i] = j;
    }
    return s.substr(0, lps.back());
}

s18-count-palindromic-subsequence-in-giv.code:
// Approach: On equal ends, count both shortened intervals plus the subsequence using both ends. On
//   unequal ends, subtract their overlap.
#include <string>
#include <vector>
using namespace std;
int countPalindromicSubsequences(const string& s) {
    // Count matching outer characters and solve the smaller interval inside.
    const long long MOD = 1000000007;
    int n = (int)s.size();
    // An empty string has no palindromic subsequences.
    if (!n) return 0;
    vector<vector<long long>> dp(n, vector<long long>(n, 0));
    for (int i = 0; i < n; ++i) dp[i][i] = 1;
    for (int length = 2; length <= n; ++length)
        for (int left = 0; left + length <= n; ++left) {
            int right = left + length - 1;
            // Matching ends can wrap each inner palindrome and add a new one.
            if (s[left] == s[right])
                dp[left][right] = (dp[left + 1][right]
                                  + dp[left][right - 1] + 1) % MOD;
            else {
                // Subtract the inner interval only when it exists, to avoid double-counting.
                long long overlap = length == 2 ? 0 : dp[left + 1][right - 1];
                dp[left][right] = (dp[left + 1][right]
                                 + dp[left][right - 1] - overlap + MOD) % MOD;
            }
        }
    return (int)dp[0][n - 1];
}
